package com.vocal.service;
import com.vocal.dto.ProductDtos.*; import com.vocal.exception.ApiException; import com.vocal.mapper.ProductMapper; import com.vocal.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.cache.annotation.Cacheable; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.util.*;
@Service @RequiredArgsConstructor public class ProductService { private final ProductRepository products; private final CategoryRepository categories; private final BannerRepository banners; private final ProductMapper mapper; @Cacheable("products") public Page<ProductResponse> search(String q,String category,BigDecimal min,BigDecimal max,Pageable pageable){return products.search(q,category,min,max,pageable).map(mapper::toResponse);} public ProductResponse bySlug(String slug){return mapper.toResponse(products.findBySlug(slug).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found")));} public List<CategoryResponse> categories(){return categories.findAll().stream().map(mapper::toResponse).toList();} public Object home(){return Map.of("banners",banners.findByActiveTrueOrderBySortOrderAsc(),"trending",search(null,null,null,null,PageRequest.of(0,8)).getContent(),"categories",categories());}}
